    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Tick" -> store.allTicks().map { it.toRow() }
        "Seller" -> store.allSellers().map { it.toRow() }
        "Listing" -> store.allListings().map { it.toRow() }
        "PublicationNotice" -> store.allPublicationNotices().map { it.toRow() }
        "SellerNotice" -> store.allSellerNotices().map { it.toRow() }
        "DraftClosure" -> store.allDraftClosures().map { it.toRow() }
        "ListingReport" -> store.allListingReports().map { it.toRow() }
        "ReporterNotice" -> store.allReporterNotices().map { it.toRow() }
        "DiscardRecord" -> store.allDiscardRecords().map { it.toRow() }
        "DiscardRefusal" -> store.allDiscardRefusals().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencing(shape: String, field: String, target: Ref.Persisted): List<Row> = when {
        shape == "Listing" && field == "seller" -> store.listingsBySeller(target).map { it.toRow() }
        shape == "SellerNotice" && field == "seller" -> store.sellerNoticesBySeller(target).map { it.toRow() }
        shape == "ListingReport" && field == "listing" -> store.listingReportsByListing(target).map { it.toRow() }
        shape == "ReporterNotice" && field == "report" -> store.reporterNoticesByReport(target).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Listing")
            questions.draftCandidates.match(filter)?.let { h -> return store.draftCandidates().map { it.toRow() } }
        if (shape == "Listing")
            questions.publishedListingCandidates.match(filter)?.let { h -> return store.publishedListingCandidates().map { it.toRow() } }
        if (shape == "ListingReport")
            questions.notifyReporterCandidates.match(filter)?.let { h -> return store.notifyReporterCandidates().map { it.toRow() } }
        if (shape == "Listing")
            questions.never1Candidates.match(filter)?.let { h -> return store.never1Candidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        else -> null
